          parts.push(payOvertime ? `Horas extra ${Number(overtime.toFixed(2))} h \xD7 $${person.overtimeRate.toFixed(2)}: $${extra.toFixed(2)}` : `Horas extra ${Number(overtime.toFixed(2))} h: registradas, no pagadas (Gerencia)`);
